"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[4885],{64885:a=>{a.exports=JSON.parse('{"slug":"ssha-otlozhili-poshliny-pokupatelyam-rossiyskoy-nefti","locale":"zh","title":"美国推迟对俄罗斯石油买家加税，俄股一周涨4.5%","description":"美国暂停对俄罗斯油气最大买家最高100%关税。解释次级关税如何运作，以及暂停对俄罗斯的意义。","blocks":[{"id":"b001","kind":"paragraph","text":"九月18日，特朗普签署格雷厄姆推动的对俄制裁法，允许对进口美国的、来自俄罗斯油气最大5个买家国家的全部商品征最高100%关税，原定十月18日生效。提前2天，特朗普签令暂停。法律允许总统告知国会措施损害美国利益后作此决定。"},{"id":"b002","kind":"paragraph","text":"国务卿鲁比奥给出两原因：不想破坏与俄乌谈判，并用60天评估全球经济后果。关税会打击印度中国，而霍尔木兹中断已造成缺油。十月16日Brent曾到$110，五月以来最高。分析师也联系十一月3日国会选举：美国燃料贵会伤选民。"},{"id":"b003","kind":"paragraph","text":"设想市场管理者处罚所有从某农户买菜者，买家付罚款，农户也受损；留客户只能降价或找不怕罚的买家。这是次级关税。九月中国购俄罗斯油气煤约9.1十亿欧元，印度4.1十亿。对它们全部输美商品最高100%税，会迫使在俄罗斯油与美国市场之间选择，或要求更大折价。"},{"id":"b004","kind":"paragraph","text":"相对国际基准的折价决定俄罗斯每桶收入。九月Urals均$92.08。印度已转向其他供应商，俄油占进口从七月51%降八月44%，更多来自美国和阿联酋。暂停只是暂时解除买家离开或索要更大折扣的威胁。"},{"id":"b005","kind":"paragraph","text":"投资者把暂停视作制裁缓和机会，高油价也支撑股市。莫斯科指数十月12日至16日涨4.51%至2426；周日十月18日周末交易接近2450，为3个月高点。卢布升得较小：十月17–19日官方美元83.62，前周84.90。十月19日早Brent跌2%至$107.6，市场预期俄罗斯燃料供应增加。"},{"id":"b006","kind":"paragraph","text":"行政令没有废法。总统随时可恢复关税，最终决定预计在十一月3日选举及十二月迈阿密G20峰会后。不加税维持现有买家与折价；加税则迫使中印重算采购，压力传至出口收入和预算。本周股涨主要反映对前者的希望，尚无保证。"},{"id":"b007","kind":"heading","text":"美国推迟了哪些针对俄油买家的关税？"},{"id":"b008","kind":"paragraph","text":"2026年九月18日法律原允许十月18日起，对俄罗斯油气最大5个买家国家输美全部商品征最高100%。十月16日总统签令暂停。"},{"id":"b009","kind":"heading","text":"对中印加税为何伤俄罗斯？"},{"id":"b010","kind":"paragraph","text":"买家必须在俄油和商品进入美国之间选择，卖家为留客降价。俄罗斯因此面临更大折扣与更少每桶收入。"},{"id":"b011","kind":"heading","text":"美国何时作最终决定？"},{"id":"b012","kind":"paragraph","text":"鲁比奥称最多60天，预计在十一月3日国会选举和十二月迈阿密G20峰会后。行政令不废法，总统随时可恢复。"}],"sources":[{"label":"特朗普签令豁免俄罗斯新制裁立法措施","url":"https://www.themoscowtimes.com/2026/10/17/trump-signs-order-exempting-russia-from-new-sanctions-legislation-a94012"},{"label":"特朗普暂停涉俄关税，为印度缓解压力","url":"https://www.outlookindia.com/international/trump-suspends-russia-linked-tariffs-india-russian-oil"},{"label":"特朗普暂缓新制裁对乌克兰的意义","url":"https://time.com/article/2026/10/17/what-trump-s-waiver-of-new-russia-sanctions-means-for-ukraine/"},{"label":"特朗普推迟严厉制裁","url":"https://www.kommersant.ru/doc/9041600"},{"label":"制裁暂缓可能增加供应，油价从5个月高位回落","url":"https://www.brecorder.com/news/40444883/oil-slips-from-5-month-high-as-trumps-russia-sanctions-waiver-may-bring-more-supplies"},{"label":"2026年九月俄罗斯化石燃料出口与制裁月度分析","url":"https://energyandcleanair.org/september-2026-monthly-analysis-of-russian-fossil-fuel-exports-and-sanctions/"},{"label":"俄罗斯石油价格上涨近一半","url":"https://lenta.ru/news/2026/10/05/urals/"},{"label":"莫斯科指数三个月上涨25%","url":"https://www.vbr.ru/novosti/investicii/2026/10/19/indeks-mosbirji-pribavil-25-za-tri-mesyaca/"},{"label":"央行将十月17–19日美元汇率降至83.62卢布","url":"https://finance.rambler.ru/economics/57237637-tsb-ponizil-kurs-dollara-na-17-19-oktyabrya-do-83-62-rublya/"},{"label":"2026年十月10日美元汇率","url":"https://ppt.ru/currencies/usd/10-10-2026"}],"sourceBodySha256":"08a9ef35b4b6638b9180eb959dc7416a99027fabfd65ad99f9ce3dbcf52878d0"}')}}]);